def gen_prime(n):
	prime = []
	prime.append(2)
	prime.append(3)
	prime.append(4)
	for i in range(5, n + 1):
		div = False
		for j in prime:
			if not i % j:
				div = True
				break
		if not div:
			prime.append(i)
	return prime
n = int(input())
prime = gen_prime(n)
prime = prime[1:]
prime.append(n)
a = [int(i) for i in input().split()]
possible = False
for i in prime:
	if not n % i:
		found = False
		l = n // i
		for k in range(0, l):
			mood = True
			for j in range(k, n, l):
				if not a[j]:
					mood = False
					break
			if mood:
				found = True
				break
		if found:
			possible = True
			break
if possible:
	print('YES')
else:
	print('NO')
